5: #[derive(Debug, Default)]
6: pub struct BpfWriter<T> {
7:     inner: T,
8:     pos: u64,
9: }
10: 
11: impl<T> BpfWriter<T> {
12:     pub fn new(inner: T) -> Self {
13:         Self { inner, pos: 0 }
14:     }
15: }
